14	static uint16_t bnep_be16(const uint8_t *p)
15	{
16	  return (uint16_t)(((uint16_t)p[0] << 8) | p[1]);
17	}
18	
19	static void bnep_put_be16(uint8_t *p, uint16_t v)
20	{
21	  p[0] = (uint8_t)(v >> 8);
22	  p[1] = (uint8_t)(v & 0xff);
23	}
