137	int32_t pw_bnep_build_filter_set(uint8_t *buf, uint32_t cap,
138	                                 const struct pw_bnep_ftype *ranges, uint8_t nranges)
139	{
140	  uint32_t need = 2u + (uint32_t)nranges * 4u;
141	  uint8_t  i;
142	
143	  if (buf == NULL || ranges == NULL || nranges == 0 || cap < need)
144	    {
145	      return -EINVAL;
146	    }
147	
148	  buf[0] = PW_BNEP_CONTROL;              /* 不带 UUID */
149	  buf[1] = PW_BNEP_CTL_FILTER_SET;
150	
151	  for (i = 0; i < nranges; i++)
152	    {
153	      bnep_put_be16(&buf[2 + i * 4], ranges[i].start);
154	      bnep_put_be16(&buf[2 + i * 4 + 2], ranges[i].end);
155	    }
156	
157	  return (int32_t)need;
158	}
