160	int32_t pw_bnep_parse_filter_rsp(const uint8_t *buf, uint32_t len, uint16_t *code)
161	{
162	  if (buf == NULL || code == NULL || len < 4)
163	    {
164	      return -EINVAL;
165	    }
166	
167	  if ((buf[0] & 0x1f) != PW_BNEP_CONTROL || buf[1] != PW_BNEP_CTL_FILTER_RSP)
168	    {
169	      return -EINVAL;
170	    }
171	
172	  *code = bnep_be16(&buf[2]);
173	  return 0;
174	}
175	
176	int32_t pw_bnep_build_data(uint8_t *buf, uint32_t cap, const uint8_t *eth,
177	                           uint32_t ethlen)
178	{
179	  if (buf == NULL || eth == NULL || ethlen < PW_BNEP_HDR_LEN - 1 ||
180	      cap < ethlen + 1u)
181	    {
182	      return -EINVAL;
183	    }
184	
185	  buf[0] = PW_BNEP_GENERAL_ETHERNET;
186	  memcpy(&buf[1], eth, ethlen);
187	  return (int32_t)(ethlen + 1u);
188	}
